# Search for any mention of years in the document
def search_json(obj, path=""):
    if isinstance(obj, str):
        if any(year in obj for year in ['1960', '1961', '1962', '1963', '1964', '1965', '1966', '1967', '1968', '1969']):
            print(f"Found at {path}: {obj[:200]}")
    elif isinstance(obj, dict):
        for k, v in obj.items():
            search_json(v, f"{path}.{k}")
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search_json(item, f"{path}[{i}]")

# Let's search just the first part
